import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('lifecycle', async () => {
  const h = await createHost();
  assert.equal(await h.run('a'), null);
  assert.equal((await h.taskStarted('a', 0)).ok, false);
  assert.deepEqual(await h.start('a'), { ok: true });
  assert.equal((await h.start('a')).ok, false);
  assert.deepEqual(await h.run('a'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
  assert.equal((await h.taskStarted('a', 3)).ok, false);
  assert.equal((await h.taskStarted('a', 0.5)).ok, false);
  assert.equal((await h.taskCompleted('a', 0)).ok, false);
  await h.taskStarted('a', 0);
  assert.equal((await h.run('a'))!.status, 'running');
  await h.taskCompleted('a', 0);
  await h.taskStarted('a', 1);
  await h.taskEvicted('a', 1);
  await h.taskStarted('a', 2);
  await h.taskCompleted('a', 2);
  assert.equal((await h.run('a'))!.status, 'running');
  await h.taskRequeued('a', 1);
  await h.taskStarted('a', 1);
  await h.taskCompleted('a', 1);
  assert.equal((await h.run('a'))!.status, 'completed');
  assert.equal((await h.cancel('a')).ok, false);
});

test('cancel and fail', async () => {
  const h = await createHost();
  await h.start('b');
  await h.taskStarted('b', 0);
  await h.taskCompleted('b', 0);
  assert.deepEqual(await h.cancel('b'), { ok: true });
  assert.deepEqual(await h.run('b'), { status: 'cancelled', task0: 'completed', task1: 'cancelled', task2: 'cancelled' });
  await h.start('c');
  await h.taskStarted('c', 2);
  await h.taskFailed('c', 2);
  assert.equal((await h.run('c'))!.status, 'failed');
  assert.equal((await h.taskStarted('c', 0)).ok, false);
});

